insert into public.recipes
  (id, title, cuisine, meal, time, servings, cal, difficulty, rating, reviews, base_rating, base_reviews, img, source, saves, cooked, description, tags, nutrition, ingredients, steps, imported, owner)
values
('crepes', 'Crepes with Orange & Honey', 'Western', 'Breakfast', 35, 3, 103, 'Easy', 4.5, 218, 4.5, 218, 'https://images.unsplash.com/photo-1519676867240-f03562e64548?auto=format&fit=crop&w=900&q=80', '{"kind":"instagram","handle":"@brunchclub","name":"Brunch Club"}'::jsonb, 1240, 312, 'Delicate French crepes folded over warm honey-soaked oranges. A bright, citrus-forward brunch that comes together in one pan.', '["Vegetarian","Brunch","Under 40 min"]'::jsonb, '{"cal":103,"protein":4,"carbs":16,"fat":3,"fiber":1,"sugar":8}'::jsonb, '[{"qty":2,"unit":"","item":"eggs","g":"Batter"},{"qty":1,"unit":"cup","item":"all-purpose flour","g":"Batter"},{"qty":0.5,"unit":"cup","item":"whole milk","g":"Batter"},{"qty":2,"unit":"tbsp","item":"butter, melted","g":"Batter"},{"qty":1,"unit":"pinch","item":"salt","g":"Batter"},{"qty":2,"unit":"","item":"oranges, segmented","g":"To finish"},{"qty":3,"unit":"tbsp","item":"honey","g":"To finish"},{"qty":1,"unit":"tbsp","item":"powdered sugar","g":"To finish"}]'::jsonb, '[{"t":"Make the batter","d":"In a large bowl, whisk the flour, eggs and salt. Gradually pour in the milk and water, whisking until smooth. Stir in the melted butter and rest 10 minutes.","timer":600},{"t":"Heat the pan","d":"Set a non-stick pan over medium heat and lightly butter it. Ladle in a thin layer of batter, swirling to coat the base."},{"t":"Cook the crepe","d":"Cook 1–2 minutes until the edges lift, then flip and cook 30 seconds more. Repeat with the rest of the batter.","timer":90},{"t":"Warm the oranges","d":"Gently warm the orange segments with honey until glossy and fragrant, about 2 minutes.","timer":120},{"t":"Plate & serve","d":"Fold each crepe into quarters, spoon over the honeyed oranges and dust with powdered sugar."}]'::jsonb, false, null),
('curry', 'Golden Chicken Curry', 'Asian', 'Dinner', 45, 4, 520, 'Medium', 4.8, 540, 4.8, 540, 'https://images.unsplash.com/photo-1631292784640-2b24be784d5d?auto=format&fit=crop&w=900&q=80', '{"kind":"tiktok","handle":"@spicekitchen","name":"Spice Kitchen"}'::jsonb, 3120, 980, 'A fragrant, golden coconut curry with tender chicken thighs, fresh ginger and a whisper of turmeric. Built for weeknights, tastes like a weekend.', '["High protein","Gluten-free","One pot"]'::jsonb, '{"cal":520,"protein":38,"carbs":22,"fat":30,"fiber":4,"sugar":6}'::jsonb, '[{"qty":1.5,"unit":"lb","item":"chicken thighs, diced","g":"Main"},{"qty":1,"unit":"can","item":"coconut milk","g":"Main"},{"qty":2,"unit":"tbsp","item":"yellow curry paste","g":"Main"},{"qty":1,"unit":"","item":"onion, sliced","g":"Aromatics"},{"qty":3,"unit":"cloves","item":"garlic, minced","g":"Aromatics"},{"qty":1,"unit":"tbsp","item":"fresh ginger, grated","g":"Aromatics"},{"qty":1,"unit":"tsp","item":"turmeric","g":"Spice"},{"qty":1,"unit":"cup","item":"jasmine rice","g":"To serve"}]'::jsonb, '[{"t":"Sear the chicken","d":"Brown the diced chicken in a hot oiled pot until golden on all sides. Remove and set aside.","timer":360},{"t":"Build the base","d":"Soften the onion, garlic and ginger, then stir in the curry paste and turmeric until fragrant.","timer":120},{"t":"Simmer","d":"Pour in the coconut milk, return the chicken and simmer gently until thickened and cooked through.","timer":1200},{"t":"Serve","d":"Spoon over steamed jasmine rice and finish with fresh coriander and lime."}]'::jsonb, false, null),
('salmon', 'Honey Glazed Salmon', 'Western', 'Dinner', 30, 2, 410, 'Medium', 4.9, 712, 4.9, 712, 'https://images.unsplash.com/photo-1467003909585-2f8a72700288?auto=format&fit=crop&w=900&q=80', '{"kind":"url","handle":"seriouseats.com","name":"Serious Eats"}'::jsonb, 4500, 1500, 'Crisp-skinned salmon lacquered in a garlic-honey-soy glaze that caramelizes in minutes. Restaurant-grade, zero fuss.', '["High protein","Under 30 min","Pescatarian"]'::jsonb, '{"cal":410,"protein":34,"carbs":18,"fat":22,"fiber":0,"sugar":15}'::jsonb, '[{"qty":2,"unit":"fillets","item":"salmon","g":"Main"},{"qty":3,"unit":"tbsp","item":"honey","g":"Glaze"},{"qty":2,"unit":"tbsp","item":"soy sauce","g":"Glaze"},{"qty":2,"unit":"cloves","item":"garlic, minced","g":"Glaze"},{"qty":1,"unit":"tbsp","item":"lemon juice","g":"Glaze"},{"qty":1,"unit":"tbsp","item":"olive oil","g":"Main"}]'::jsonb, '[{"t":"Mix the glaze","d":"Whisk together honey, soy, garlic and lemon juice in a small bowl."},{"t":"Sear skin-side down","d":"Sear the salmon in hot oil, skin-side down, until the skin is crisp, about 4 minutes.","timer":240},{"t":"Glaze & finish","d":"Flip, pour in the glaze and spoon over the fish until thick and glossy, 2–3 minutes.","timer":180},{"t":"Rest & serve","d":"Rest 2 minutes, then serve with greens and the pan sauce."}]'::jsonb, false, null),
('pasta', 'Spaghetti Pomodoro', 'Italian', 'Dinner', 25, 2, 480, 'Easy', 4.6, 389, 4.6, 389, 'https://images.unsplash.com/photo-1551183053-bf91a1d81141?auto=format&fit=crop&w=900&q=80', '{"kind":"manual","handle":"You","name":"My Recipe"}'::jsonb, 870, 410, 'The purist’s tomato pasta: sweet San Marzanos, good olive oil, torn basil. Five ingredients, endless comfort.', '["Vegetarian","Quick","Pantry"]'::jsonb, '{"cal":480,"protein":14,"carbs":78,"fat":12,"fiber":6,"sugar":9}'::jsonb, '[{"qty":200,"unit":"g","item":"spaghetti","g":"Main"},{"qty":1,"unit":"can","item":"San Marzano tomatoes","g":"Sauce"},{"qty":3,"unit":"cloves","item":"garlic, sliced","g":"Sauce"},{"qty":3,"unit":"tbsp","item":"olive oil","g":"Sauce"},{"qty":1,"unit":"handful","item":"fresh basil","g":"To finish"}]'::jsonb, '[{"t":"Boil the pasta","d":"Cook spaghetti in well-salted water until al dente. Reserve a cup of pasta water.","timer":540},{"t":"Start the sauce","d":"Gently sizzle the garlic in olive oil, then add the crushed tomatoes and simmer.","timer":600},{"t":"Toss together","d":"Toss the pasta in the sauce with a splash of pasta water until silky. Finish with basil."}]'::jsonb, false, null),
('bowl', 'Green Goddess Bowl', 'Healthy', 'Lunch', 15, 1, 320, 'Easy', 4.7, 256, 4.7, 256, 'https://images.unsplash.com/photo-1512621776951-a57141f2eefd?auto=format&fit=crop&w=900&q=80', '{"kind":"instagram","handle":"@plantplates","name":"Plant Plates"}'::jsonb, 1980, 640, 'Crunchy greens, creamy avocado and a herby goddess dressing. The lunch that makes you feel like you have your life together.', '["Vegan","Under 15 min","High fiber"]'::jsonb, '{"cal":320,"protein":9,"carbs":28,"fat":20,"fiber":11,"sugar":5}'::jsonb, '[{"qty":2,"unit":"cups","item":"mixed greens","g":"Bowl"},{"qty":1,"unit":"","item":"avocado, sliced","g":"Bowl"},{"qty":0.5,"unit":"cup","item":"cooked quinoa","g":"Bowl"},{"qty":0.25,"unit":"cup","item":"green goddess dressing","g":"Dressing"},{"qty":1,"unit":"tbsp","item":"pumpkin seeds","g":"Bowl"}]'::jsonb, '[{"t":"Build the base","d":"Layer the greens and quinoa in a wide bowl."},{"t":"Top it","d":"Fan over the avocado, scatter pumpkin seeds."},{"t":"Dress & eat","d":"Drizzle generously with goddess dressing and toss at the table."}]'::jsonb, false, null),
('pizza', 'Margherita Pizza', 'Italian', 'Dinner', 40, 4, 600, 'Medium', 4.7, 901, 4.7, 901, 'https://images.unsplash.com/photo-1574071318508-1cdbab80d002?auto=format&fit=crop&w=900&q=80', '{"kind":"youtube","handle":"Pizza Nerd","name":"Pizza Nerd"}'::jsonb, 5200, 1820, 'Blistered crust, San Marzano sauce, fresh mozzarella and basil. The whole point of owning an oven.', '["Vegetarian","Crowd-pleaser"]'::jsonb, '{"cal":600,"protein":24,"carbs":72,"fat":24,"fiber":4,"sugar":6}'::jsonb, '[{"qty":1,"unit":"ball","item":"pizza dough","g":"Base"},{"qty":0.5,"unit":"cup","item":"tomato sauce","g":"Topping"},{"qty":8,"unit":"oz","item":"fresh mozzarella","g":"Topping"},{"qty":1,"unit":"handful","item":"fresh basil","g":"Topping"},{"qty":2,"unit":"tbsp","item":"olive oil","g":"Topping"}]'::jsonb, '[{"t":"Preheat hot","d":"Heat the oven and a pizza steel as hot as it goes, at least 30 minutes.","timer":1800},{"t":"Stretch & top","d":"Stretch the dough, spread sauce thinly and dot with torn mozzarella."},{"t":"Bake","d":"Bake until the crust is charred and the cheese bubbles, 6–8 minutes.","timer":420},{"t":"Finish","d":"Top with fresh basil and a drizzle of olive oil."}]'::jsonb, false, null),
('tacos', 'Street-Style Tacos', 'Local', 'Dinner', 30, 3, 450, 'Easy', 4.8, 633, 4.8, 633, 'https://images.unsplash.com/photo-1565299585323-38d6b0865b47?auto=format&fit=crop&w=900&q=80', '{"kind":"tiktok","handle":"@tacotuesday","name":"Taco Tuesday"}'::jsonb, 2700, 1100, 'Charred, marinated meat tucked into warm corn tortillas with onion, cilantro and a squeeze of lime. Napkins mandatory.', '["High protein","Quick"]'::jsonb, '{"cal":450,"protein":28,"carbs":36,"fat":22,"fiber":5,"sugar":3}'::jsonb, '[{"qty":1,"unit":"lb","item":"skirt steak","g":"Main"},{"qty":8,"unit":"","item":"corn tortillas","g":"Main"},{"qty":1,"unit":"","item":"white onion, diced","g":"Toppings"},{"qty":1,"unit":"bunch","item":"cilantro","g":"Toppings"},{"qty":2,"unit":"","item":"limes","g":"Toppings"}]'::jsonb, '[{"t":"Sear the steak","d":"Sear the steak hard, then rest and chop into bite-size pieces.","timer":480},{"t":"Warm tortillas","d":"Char the tortillas directly over the flame until soft and spotty."},{"t":"Assemble","d":"Pile on the meat, top with onion and cilantro, finish with lime."}]'::jsonb, false, null),
('oats', 'Berry Overnight Oats', 'Healthy', 'Breakfast', 10, 2, 290, 'Easy', 4.4, 178, 4.4, 178, 'https://images.unsplash.com/photo-1490645935967-10de6ba17061?auto=format&fit=crop&w=900&q=80', '{"kind":"manual","handle":"You","name":"My Recipe"}'::jsonb, 1320, 720, 'Stir it tonight, grab it tomorrow. Creamy oats, chia and a tumble of berries — breakfast on autopilot.', '["Vegan","Make ahead","High fiber"]'::jsonb, '{"cal":290,"protein":10,"carbs":44,"fat":8,"fiber":9,"sugar":14}'::jsonb, '[{"qty":1,"unit":"cup","item":"rolled oats","g":"Base"},{"qty":1,"unit":"cup","item":"almond milk","g":"Base"},{"qty":2,"unit":"tbsp","item":"chia seeds","g":"Base"},{"qty":1,"unit":"cup","item":"mixed berries","g":"Top"},{"qty":1,"unit":"tbsp","item":"maple syrup","g":"Base"}]'::jsonb, '[{"t":"Combine","d":"Stir oats, milk, chia and maple in a jar."},{"t":"Chill overnight","d":"Cover and refrigerate at least 4 hours, ideally overnight.","timer":600},{"t":"Top & go","d":"Top with berries in the morning and eat cold."}]'::jsonb, false, null),
('lassi', 'Mango Lassi', 'Drinks', 'Drink', 5, 2, 180, 'Easy', 4.5, 142, 4.5, 142, 'https://images.unsplash.com/photo-1601050690597-df0568f70950?auto=format&fit=crop&w=900&q=80', '{"kind":"instagram","handle":"@cooldrinks","name":"Cool Drinks"}'::jsonb, 640, 290, 'Cold, creamy and golden — ripe mango blended with yogurt and a pinch of cardamom.', '["Vegetarian","Under 5 min"]'::jsonb, '{"cal":180,"protein":6,"carbs":32,"fat":4,"fiber":2,"sugar":28}'::jsonb, '[{"qty":2,"unit":"cups","item":"ripe mango","g":"Blend"},{"qty":1,"unit":"cup","item":"yogurt","g":"Blend"},{"qty":0.5,"unit":"cup","item":"milk","g":"Blend"},{"qty":1,"unit":"pinch","item":"cardamom","g":"Blend"}]'::jsonb, '[{"t":"Blend","d":"Blend everything until completely smooth."},{"t":"Serve","d":"Pour over ice and dust with cardamom."}]'::jsonb, false, null),
('lava', 'Chocolate Lava Cake', 'Dessert', 'Dessert', 25, 2, 480, 'Medium', 4.9, 820, 4.9, 820, 'https://images.unsplash.com/photo-1606313564200-e75d5e30476c?auto=format&fit=crop&w=900&q=80', '{"kind":"url","handle":"bonappetit.com","name":"Bon Appétit"}'::jsonb, 6100, 2010, 'Cakey edges, molten middle. Mix in one bowl, bake in twelve minutes, and look like a genius.', '["Vegetarian","Date night"]'::jsonb, '{"cal":480,"protein":8,"carbs":52,"fat":28,"fiber":3,"sugar":38}'::jsonb, '[{"qty":4,"unit":"oz","item":"dark chocolate","g":"Batter"},{"qty":0.5,"unit":"cup","item":"butter","g":"Batter"},{"qty":2,"unit":"","item":"eggs","g":"Batter"},{"qty":0.5,"unit":"cup","item":"sugar","g":"Batter"},{"qty":0.25,"unit":"cup","item":"flour","g":"Batter"}]'::jsonb, '[{"t":"Melt","d":"Melt chocolate and butter together until glossy."},{"t":"Mix","d":"Whisk in eggs and sugar, then fold in the flour."},{"t":"Bake","d":"Bake in buttered ramekins until the edges set but centers jiggle, 11–12 min.","timer":720},{"t":"Invert","d":"Rest 1 minute, invert onto a plate and serve at once."}]'::jsonb, false, null),
('matcha', 'Iced Matcha Latte', 'Drinks', 'Drink', 5, 1, 120, 'Easy', 4.3, 96, 4.3, 96, 'https://images.unsplash.com/photo-1536256263959-770b48d82b0a?auto=format&fit=crop&w=900&q=80', '{"kind":"tiktok","handle":"@matchamood","name":"Matcha Mood"}'::jsonb, 510, 230, 'Whisked ceremonial matcha over cold milk and ice. Calmer than coffee, prettier too.', '["Vegetarian","Under 5 min"]'::jsonb, '{"cal":120,"protein":4,"carbs":14,"fat":5,"fiber":1,"sugar":10}'::jsonb, '[{"qty":1,"unit":"tsp","item":"matcha powder","g":"Drink"},{"qty":2,"unit":"tbsp","item":"hot water","g":"Drink"},{"qty":1,"unit":"cup","item":"oat milk","g":"Drink"},{"qty":1,"unit":"tsp","item":"maple syrup","g":"Drink"}]'::jsonb, '[{"t":"Whisk","d":"Whisk matcha with hot water until frothy and lump-free."},{"t":"Pour","d":"Pour over iced milk and sweeten to taste."}]'::jsonb, false, null),
('roast', 'Lemon Herb Roast Chicken', 'Western', 'Dinner', 90, 5, 650, 'Medium', 4.9, 1120, 4.9, 1120, 'https://images.unsplash.com/photo-1598103442097-8b74394b95c6?auto=format&fit=crop&w=900&q=80', '{"kind":"url","handle":"nytcooking.com","name":"NYT Cooking"}'::jsonb, 7300, 2400, 'Golden, crackling skin and lemony herb butter under every inch. The Sunday dinner that owns the table.', '["High protein","Gluten-free","Sunday"]'::jsonb, '{"cal":650,"protein":52,"carbs":4,"fat":46,"fiber":1,"sugar":1}'::jsonb, '[{"qty":1,"unit":"","item":"whole chicken","g":"Main"},{"qty":4,"unit":"tbsp","item":"butter, softened","g":"Herb butter"},{"qty":1,"unit":"","item":"lemon, halved","g":"Main"},{"qty":4,"unit":"sprigs","item":"thyme","g":"Herb butter"},{"qty":1,"unit":"head","item":"garlic","g":"Main"}]'::jsonb, '[{"t":"Season","d":"Rub the chicken all over and under the skin with herb butter; salt generously."},{"t":"Roast","d":"Roast at high heat, basting once, until the juices run clear, about 75 minutes.","timer":4500},{"t":"Rest","d":"Rest 15 minutes before carving so the juices settle.","timer":900}]'::jsonb, false, null)
